const raw = items[0].json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const headers = raw.headers || {};
const secret = String(headers['x-ram-hospital-secret'] || headers['X-Ram-Hospital-Secret'] || '');
const expected = String(body.webhookSecret || '');
if (expected && secret && secret !== expected) { throw new Error('Ram Hospital webhook secret was not accepted'); }
const guestEmail = String(body.guestEmail || body.email || '').trim().toLowerCase();
const staffEmail = String(body.staffEmail || body.alertEmail || 'itsolutions.mm@gmail.com').trim().toLowerCase();
const chatId = String(body.telegramChatId || '').trim();
const telegramText = String(body.telegramText || body.text || '').trim();
const guestText = String(body.guestText || '').trim();
const guestHtmlRaw = String(body.guestHtml || '').trim();
const guestHtml = guestHtmlRaw || (guestText ? '<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.6;color:#1a2330"><p>' + guestText.replace(/\n/g, '<br/>') + '</p></div>' : '<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.6;color:#1a2330"><p>We received your visit request. A coordinator will continue with you shortly.</p></div>');
const staffHtml = String(body.staffHtml || body.html || '').trim();
const guestSubject = String(body.guestSubject || 'We received your visit request');
const staffSubject = String(body.staffSubject || body.subject || 'Ram Hospital inquiry');
const hasGuest = guestEmail.includes('@') && guestEmail !== staffEmail;
const mailNote = hasGuest ? ('\nAuto-mail → ' + guestEmail) : '\nAuto-mail → skipped (no guest email)';
const tg = (telegramText || staffSubject) + mailNote;
return [{ json: { ...body, guestEmail, hasGuest, staffEmail, toEmail: staffEmail, telegramChatId: chatId, telegramText: tg, text: tg, guestText, guestHtml, staffHtml, html: staffHtml || guestHtml, guestSubject, subject: staffSubject } }];

const row = items[0].json;
const email = String(row.guestEmail || '').trim().toLowerCase();
if (!email.includes('@')) return [];
if (email === String(row.staffEmail || '').trim().toLowerCase()) return [];
return [{ json: row }];
